package com.example.domain.model.i18n

internal object DuaId1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Ketika Bangun Tidur", "Segala puji bagi Allah yang telah menghidupkan kami setelah mematikan kami (tidur), dan hanya kepada-Nya kami kembali.", "Dibaca segera setelah bangun tidur sebagai rasa syukur kepada Allah.", "Nabi ﷺ membacanya saat bangun tidur — mengawali hari dengan syukur dan mengingat akhirat."),
        "dua_leaving_home" to DuaText("Ketika Keluar Rumah", "Dengan nama Allah, aku bertawakal kepada Allah, tiada daya dan kekuatan kecuali dengan Allah.", "Dibaca saat keluar rumah untuk memohon perlindungan.", "Dikatakan kepadanya: engkau telah diberi petunjuk, dicukupi, dan dilindungi, lalu setan menjauh darinya."),
        "dua_anxiety_distress" to DuaText("Doa Kegelisahan dan Kesedihan", "Ya Allah, aku berlindung kepada-Mu dari rasa gelisah dan sedih, dari kelemahan dan kemalasan, dari sifat kikir dan pengecut, dari beratnya utang dan tekanan orang lain.", "Saat gelisah, sedih, terlilit utang, atau tertekan secara mental.", "Nabi ﷺ sering membaca doa ini untuk berlindung dari kesedihan, kemalasan, dan utang."),
        "dua_sayyidul_istighfar" to DuaText("Sayyidul Istighfar", "Ya Allah, Engkau adalah Tuhanku, tiada Tuhan selain Engkau. Engkau menciptakanku dan aku adalah hamba-Mu. Aku akan setia pada perjanjian dan janjiku kepada-Mu semampuku. Aku berlindung kepada-Mu dari keburukan yang telah kuperbuat. Aku mengakui nikmat-Mu kepadaku dan aku mengakui dosaku, maka ampunilah aku, karena tiada yang mengampuni dosa selain Engkau.", "Dibaca pagi dan petang — doa taubat terbaik yang diajarkan Nabi ﷺ.", "Siapa membacanya di sore hari dengan penuh keyakinan lalu meninggal malam itu, ia masuk surga; demikian pula jika dibaca di pagi hari."),
        "dua_parents" to DuaText("Doa untuk Kedua Orang Tua", "Ya Tuhanku, sayangilah keduanya sebagaimana mereka telah mendidikku sewaktu kecil.", "Doa Al-Qur'an untuk orang tua atas jasa mendidik di masa kecil.", "Allah sendiri memerintahkan doa ini untuk orang tua di dalam Al-Qur'an."),
        "dua_entering_mosque" to DuaText("Memasuki Masjid", "Ya Allah, bukakanlah untukku pintu-pintu rahmat-Mu.", "Dibaca saat memasuki masjid dengan kaki kanan.", "Nabi ﷺ mengajarkan doa ini ketika memasuki masjid."),
        "dua_morning_asbahna" to DuaText("Dzikir Pagi", "Kami memasuki waktu pagi dan kerajaan hanya milik Allah, segala puji bagi Allah, tiada Tuhan selain Allah Yang Maha Esa, tiada sekutu bagi-Nya, milik-Nya kerajaan dan pujian, dan Dia Maha Kuasa atas segala sesuatu.", "Doa sunnah yang dibaca pada waktu pagi.", "Mengawali hari dengan pengakuan atas kerajaan dan keesaan Allah."),
        "dua_evening_amsayna" to DuaText("Dzikir Sore", "Kami memasuki waktu sore dan kerajaan hanya milik Allah, segala puji bagi Allah, tiada Tuhan selain Allah Yang Maha Esa, tiada sekutu bagi-Nya, milik-Nya kerajaan dan pujian, dan Dia Maha Kuasa atas segala sesuatu.", "Doa sunnah yang dibaca pada waktu sore.", "Mengawali malam dengan pengakuan atas kerajaan dan keesaan Allah."),
        "dua_before_sleep" to DuaText("Sebelum Tidur", "Dengan nama-Mu ya Allah, aku mati (tidur) dan aku hidup (bangun).", "Dibaca setelah berbaring di tempat tidur.", "Nabi ﷺ membaca doa ini sebelum tidur."),
        "dua_travel" to DuaText("Doa Bepergian", "Maha Suci Allah yang telah menundukkan ini untuk kami padahal kami sebelumnya tidak mampu menguasainya, dan sesungguhnya kami akan kembali kepada Tuhan kami.", "Dibaca saat naik kendaraan setelah bertakbir tiga kali.", "Doa sunnah perjalanan untuk perlindungan dan keberkahan."),
        "dua_ayatul_kursi" to DuaText("Ayat Kursi Setelah Shalat", "Allah, tiada Tuhan selain Dia, Yang Maha Hidup, Yang terus-menerus mengurus makhluk-Nya. Tidak mengantuk dan tidak tidur. Milik-Nya apa yang di langit dan di bumi. Siapa yang dapat memberi syafaat di sisi-Nya tanpa izin-Nya? Dia mengetahui apa yang di hadapan dan di belakang mereka. Mereka tidak mengetahui sedikit pun dari ilmu-Nya kecuali yang Dia kehendaki. Kursi-Nya meliputi langit dan bumi, dan Dia tidak merasa berat memelihara keduanya. Dialah Yang Maha Tinggi lagi Maha Besar.", "Dibaca setelah setiap shalat fardhu dan sebelum tidur.", "Siapa membacanya setelah tiap shalat fardhu, tiada yang menghalanginya masuk surga kecuali kematian; sebelum tidur, ia terjaga hingga pagi."),
        "dua_hasbunallah" to DuaText("Hasbunallahu wa Ni'mal Wakil", "Cukuplah Allah bagi kami dan Dialah sebaik-baik pelindung.", "Dibaca saat takut kepada musuh atau bahaya besar.", "Diucapkan oleh Nabi Ibrahim (a.s.) saat dilemparkan ke dalam api, dan oleh Nabi ﷺ saat menghadapi bahaya."),
        "dua_entering_home" to DuaText("Memasuki Rumah", "Dengan nama Allah kami masuk, dan dengan nama Allah kami keluar, dan kepada Allah Tuhan kami, kami bertawakal.", "Dibaca saat memasuki rumah sambil menyebut nama Allah dan mengucap salam.", "Siapa yang mengingat Allah saat masuk rumah dan saat makan, setan berkata: tidak ada tempat menginap dan makan malam bagi kalian."),
        "dua_yunus" to DuaText("Doa Nabi Yunus (a.s.)", "Tiada Tuhan selain Engkau, Maha Suci Engkau, sesungguhnya aku termasuk orang-orang yang zalim.", "Doa Nabi Yunus (a.s.) di dalam perut ikan — untuk setiap kesulitan.", "Tidaklah seorang muslim berdoa dengan doa ini dalam suatu perkara melainkan Allah mengabulkannya."),
        "dua_karb" to DuaText("Doa Saat Kesulitan Berat", "Tiada Tuhan selain Allah Yang Maha Agung lagi Maha Penyantun. Tiada Tuhan selain Allah, Tuhan pemilik Arsy yang agung. Tiada Tuhan selain Allah, Tuhan langit dan bumi, dan Tuhan Arsy yang mulia.", "Dibaca saat kesulitan dan kesempitan yang berat.", "Nabi ﷺ membacanya saat menghadapi kesulitan besar."),
    )
}
